exactSources.saveProfile:
function saveProfile(){
  // v117: top-level schema/backfill calls made while the one-file bundle is still
  // declaring later modules must never refresh the whole UI. Defer them into one
  // final save after every dataset/renderer exists.
  if(!appBootComplete){bootProfileSavePending=true;return true;}
  if(profileWriteBlocked||profileConflictBlocked){restoreCommittedProfileInMemory(true);return false;}
  if(!acquireProfileWriteLease()){
    restoreCommittedProfileInMemory(true);
    markProfileConflict('別のFE QUEST画面がいま学習データを書き込んでいます');return false;
  }
  let saved=false;
  try{
    profile=stampProfileForSave(profile);
    const result=writeCurrentProfile(profile,{preservePrevious:true});
    profile=result.profile;rememberCommittedProfile(profile);clearProfileSaveFailure();
    saved=true;
  }catch(e){
    restoreCommittedProfileInMemory(false);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT'){markProfileConflict();return false}
    profileWriteBlocked=true;
    console.warn('学習データの保存に失敗しました。',e);
    setTimeout(()=>showAppNotice('error','保存できませんでした','現在の学習データは最後に正常保存できた状態へ戻しました。ページを再読み込みすると改善する場合があります。','再読み込み',()=>location.reload()),0);
    setTimeout(()=>refreshPwaHealth?.(),0);
    return false;
  }finally{releaseProfileWriteLease()}

  // A recovery-checkpoint or UI-rendering bug must never be misclassified as a
  // storage failure. Persistence has already succeeded at this point.
  try{queueRecoveryCheckpoint('autosave',false)}catch(e){console.warn('Recovery checkpoint queue failed',e)}
  try{refreshProfileUI()}catch(e){
    console.warn('UI refresh failed after a successful save',e);
    setTimeout(()=>reportGlobalError?.(),0);
  }
  return saved;
}

exactSources.completeLesson:
function(){
  const lessonBefore=activeLesson;
  const reviewBefore=activeReviewJourneyId?journeyFor(activeReviewJourneyId):null;
  const isReviewLesson=!!reviewBefore&&reviewBefore.stage==='relearn'&&reviewBefore.lessonId===lessonBefore;
  const isCoreLesson=!!LESSONS[lessonBefore]?.core;
  _completeLessonV65();

  // 科目Aコアは「教材を読む→テーマ演習を終える」までを今日の学習1枠とする。
  // 復習ルート内の教材読み直しは新規学習枠として数えない。
  if(!isReviewLesson&&!isCoreLesson)markDailyTask('lesson',{lessonId:lessonBefore});
}

exactSources._completeLessonV65:
function completeLesson(){
  const lesson=LESSONS[activeLesson];
  const old=profile.lessonProgress[activeLesson]||0;
  profile.lessonProgress[activeLesson]=100;
  // 教材を読んだ事実と、問題で確認した習熟度は分けて扱う。
  // 習熟度は診断・問題演習の回答結果から更新する。
  profile.xp += old<100?50:15;
  saveProfile();
  updateCourseUI();

  const reviewLessonCompleted=activeReviewJourneyId?markJourneyLessonDone(activeReviewJourneyId,activeLesson):false;
  const reviewJourneyId=reviewLessonCompleted?activeReviewJourneyId:null;

  if(lesson.core){
    const completedId=activeLesson;
    const earned=old<100?50:15;
    lessonCompleteMode=false;
    popToast(`${lesson.title} 学習完了　+${earned} XP`);
    if(reviewLessonCompleted){
      activeReviewJourneyId=null;
      showScreen('problems');
      startQuiz('journey:'+reviewJourneyId);
    }else{
      showScreen('problems');
      startQuiz('coretopic:'+completedId);
    }
    return;
  }

  document.getElementById('lessonHeadline').textContent='レッスン完了！';
  document.getElementById('lessonCopy').textContent=reviewLessonCompleted?'次は類題へ進みます。':'';
  document.getElementById('lessonStage').innerHTML=`
    <div class="lesson-complete">
      <div class="lesson-complete-icon">🏆</div>
      <h2>${lesson.title} クリア</h2>
      <div class="lesson-complete-xp">+${old<100?50:15} XP</div>
      <span class="mastery-change">教材の学習を記録しました</span>
      ${reviewLessonCompleted?'<button class="lesson-review-next" id="lessonReviewNext">類題で確認 →</button>':''}
      ${(!reviewLessonCompleted && CORE_A_IDS.includes(activeLesson))?`<button class="lesson-topic-practice" id="lessonTopicPractice">このテーマを問題で仕上げる →</button><div class="topic-practice-note">${CORE_A_TOPIC_PRACTICE_COUNTS[activeLesson]||3}問で、この解説だけで判断できる内容を確認します。複数テーマをまたぐ比較問題は章末チェックで扱います。</div>`:''}
    </div>`;
  if(reviewLessonCompleted){
    document.getElementById('lessonReviewNext')?.addEventListener('click',()=>{const id=reviewJourneyId;activeReviewJourneyId=null;showScreen('problems');startQuiz('journey:'+id);});
  }
  document.getElementById('lessonTopicPractice')?.addEventListener('click',()=>{
    const id=activeLesson;
    showScreen('problems');
    startQuiz('coretopic:'+id);
  });
  document.getElementById('lessonCheck').className='lesson-check';
  document.getElementById('lessonPrev').style.display='none';
  document.getElementById('lessonStepLabel').textContent='完了';
  const next=document.getElementById('lessonNext');
  next.textContent='学習マップへ';
  lessonCompleteMode=true;
}

exactSources.registerReviewJourney:
function registerReviewJourney(q,source='practice'){
  const id=q?.sourceId||q?.id;if(!id)return null;
  const base=questionById(id)||q;
  const old=profile.reviewJourneys[id]||{};
  const lessonId=lessonForQuestion(base);
  const wasStable=old.stage==='stable';
  profile.reviewJourneys[id]={
    ...old,id,cat:base.cat,concept:base.concept,lessonId,
    stage:wasStable?(lessonId?'relearn':'verify'):(old.stage|| (lessonId?'relearn':'verify')),
    misses:(old.misses||0)+1,lastWrong:localDateISO(0),source,
    due:profile.qStats?.[id]?.due||localDateISO(1),completedAt:wasStable?null:old.completedAt
  };
  saveProfile();
  return profile.reviewJourneys[id];
}

exactSources.subjectBPerformanceFlushV254:
function subjectBPerformanceFlushV254(layer){
  const st=subjectBPerformanceStateV254(layer);
  if(st.flushed)return 0;
  subjectBPerformancePauseV254(st);
  let added=0;
  Object.keys(st.frozen).forEach(key=>{
    const meta=st.meta[key]||{};
    if(subjectBPerformanceRecordV254({layer,sourceId:meta.sourceId,level:meta.level,ok:!!st.firstOk[key],elapsedMs:st.frozen[key],at:st.firstAt[key]}))added++;
  });
  st.flushed=true;
  return added;
}

exactSources.markDailyTask:
function markDailyTask(type,meta={}){
  const rec=getDailyRecord(),tasks=ensureTodayPlanSnapshot();
  const task=tasks.find(t=>dailyTaskMatches(t,type,meta));
  if(!task)return false;
  const slot=dailyTaskSlot(task);
  if(!rec.done[slot]){
    rec.done[slot]=true;
    addActivity(task.minutes,slot);
  }else{
    persistProfileSilently();
  }
  renderDailyPlan();
  renderPlannerScreen();
  return true;
}

exactSources.buildTodayTasks:
function buildTodayTasks(){
  const daysNow=examDaysRemaining();
  const totalNow=effectiveStudyMinutes();
  if(daysNow!=null&&daysNow>=0&&daysNow<=7)return buildTaperTodayTasks(daysNow,totalNow);
  const alloc=taskAllocation(totalNow);
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;
  const lesson=nextLessonChoice();
  const b=nextBChoice(alloc.subjectB);
  const bMinutes=(b.mode==='compound'||b.mode==='securityMock')?Math.min(20,alloc.subjectB):alloc.subjectB;
  const lessonMinutes=alloc.lesson+Math.max(0,alloc.subjectB-bMinutes);
  const weak=weakestSkill();
  const days=examDaysRemaining();
  const finalPhase=days!=null&&days<=14;

  const rxReady=window.FEQUEST_RX_READY===true;
  const rx=rxReady?recommendedPrescription():{kind:'knowledge',cat:lesson.skill,reason:'データ不足'};
  const rxMeta=rxReady?prescriptionMeta(rx):{icon:'📘',title:lesson.title,desc:'未完了教材を優先'};
  const useRx=rxReady && rx.kind!=='knowledge';

  let learnTask;
  if(lesson.complete){
    const focus=shortFinalFocusRecommendation();
    learnTask={
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:lessonMinutes,focus
    };
  }else if(useRx){
    learnTask={
      type:'prescription',icon:rxMeta.icon,bg:'blue',
      title:rxMeta.title,desc:`原因「${rx.reason}」に合わせて自動処方`,
      minutes:lessonMinutes,rx
    };
  }else{
    learnTask={
      type:'lesson',icon:'📘',bg:'blue',
      title:lesson.title,desc:`${lesson.skill}・未完了教材を優先`,
      minutes:lessonMinutes,lessonId:lesson.id
    };
  }

  return [
    {
      type:'review',icon:'🧠',bg:'green',
      title:'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`復習期限の問題 ${due}問を優先`:`今日の復習期限はなし。「${weak}」を補強`,
      minutes:alloc.review
    },
    learnTask,
    {
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`プログラムトレース：${b.title}`:b.mode==='security'?`セキュリティ：${b.title}`:b.mode==='compound'?`複合演習：${b.title}`:b.mode==='securityMock'?b.title:`実戦：${b.title}`,
      desc:b.mode==='trace'?'科目B アルゴリズム':b.mode==='security'?'科目B 情報セキュリティ':b.mode==='compound'?'科目B アルゴリズム・20分実戦':b.mode==='securityMock'?'科目B セキュリティ・20分実戦':'科目B 実戦',
      minutes:bMinutes,bmode:b.mode,bid:b.id
    },
    {
      type:'boss',icon:'👑',bg:'yellow',
      title:finalPhase?'直前総合チェック':'今日の総合チェック',
      desc:finalPhase?'判断3問＋適用2問・分野を散らして5問':'全分野から5問・仕上げチェック',
      minutes:alloc.boss
    }
  ];
}

qStats.source:
function gradeCurrentQuestion(){
  const q=quizItems[quizIndex];
  const ok=quizSelected===q.a;
  const statId=q.sourceId||q.id;
  const st=profile.qStats[statId];
  const selectedNow=quizSelected;
  const attemptSeconds=Math.max(1,Math.round((Date.now()-quizQuestionStartedAt)/1000));

  // 通常演習ではすべて「初回誤答→ヒント→1回だけ再挑戦」に統一する。
  // v121: 誤答時はヒント本文だけを表示し、採点ルールやメタ説明は出さない。
  // 模試は別の試験UIなので、この関数を通らない。
  if(!ok && quizRetryCount===0){
    quizRetryCount=1;
    quizFirstAttemptWrong=true;
    quizWrongCount++;
    quizFirstAttemptSeconds=attemptSeconds;

    // 成績・正答率・忘却モデルへ入れるのは最初の回答だけ。
    st.attempts++;
    st.last=localDateISO(0);
    st.streak=0;
    adaptiveMemoryUpdate(st,'wrong',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,-1);
    profile.xp+=2;
    registerReviewJourney(q,String(quizMode).startsWith('journey:')?'journey':'practice');
    saveProfile();

    const selectedBtn=document.querySelectorAll('.quiz-option')[selectedNow];
    if(selectedBtn){
      selectedBtn.classList.remove('selected');
      selectedBtn.classList.add('first-wrong');
      selectedBtn.disabled=true;
    }
    quizSelected=null;
    quizQuestionStartedAt=Date.now();

    document.getElementById('quizResultTitle').textContent='💡 ヒント';
    document.getElementById('quizExplanation').textContent=q.hint;
    document.getElementById('quizHint').textContent='';
    document.getElementById('quizExplain').classList.add('show');
    document.getElementById('quizHintBtn').style.display='none';
    document.querySelector('.quiz-actions')?.classList.add('single-primary');
    document.getElementById('quizSubmit').textContent='もう一度回答する';
    return;
  }

  quizAnswered=true;
  stopQuestionPacer();

  document.querySelectorAll('.quiz-option').forEach((btn,i)=>{
    btn.disabled=true;
    btn.classList.remove('selected','first-wrong');
    if(i===q.a) btn.classList.add('correct');
    else if(i===selectedNow && !ok) btn.classList.add('wrong');
  });

  const recovered=ok && quizFirstAttemptWrong;
  document.getElementById('quizResultTitle').textContent=recovered?'🔄 再挑戦で正解！':ok?'⭕ 正解！':'❌ 不正解';
  renderFinalQuizExplanation(q);
  const finalHint=(q.hint && !String(q.exp||'').includes(q.hint))?`確認ポイント：${q.hint}`:'';
  document.getElementById('quizHint').textContent=finalHint;
  document.getElementById('quizExplain').classList.add('show');
  document.getElementById('quizHintBtn').style.display='none';
  document.querySelector('.quiz-actions')?.classList.add('single-primary');

  const answerExplain=document.getElementById('quizExplain');
  answerExplain.querySelector('.variant-source-note')?.remove();
  answerExplain.querySelector('.review-route-inline')?.remove();
  answerExplain.querySelector('.memory-next-note')?.remove();
  const retryNote=answerExplain.querySelector('.retry-note');
  if(retryNote) retryNote.remove();

  if(!quizFirstAttemptWrong){
    // 初回正解だけが「正解」として正答率へ入る。
    quizCorrectCount++;
    quizEarnedXp+=10;
    st.attempts++;
    st.correct++;
    st.last=localDateISO(0);
    st.streak=(st.streak||0)+1;
    adaptiveMemoryUpdate(st,'correct',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,1);
    profile.xp+=10;
  }else if(recovered){
    // 再挑戦成功は別指標。attempts/correctは増やさない。
    quizRecoveredCount++;
    st.recovered=(st.recovered||0)+1;
    st.streak=0;
    adaptiveMemoryUpdate(st,'recovered',quizFirstAttemptSeconds||attemptSeconds,quizPickedReason,true);
    applyQuestionSkillDelta(q,0.25);
    profile.xp+=5;
  }else{
    // 2回目も不正解でも、同じ問題を2回誤答として数えない。
    st.retryFailures=(st.retryFailures||0)+1;
  }

  // 最初に間違えた問題は、再挑戦で正解しても原因を記録できる。
  if(quizFirstAttemptWrong) document.getElementById('reasonBox').classList.add('show');

  if(String(quizMode).startsWith('journey:')){
    const jid=String(quizMode).slice(8);
    markJourneyAnswer(jid,!quizFirstAttemptWrong&&ok);
  }

  sessionLog.push({
    id:statId,variantId:q.variant?q.id:null,cat:q.cat,concept:q.concept,
    ok:!quizFirstAttemptWrong&&ok,
    recovered,
    retryFailed:quizFirstAttemptWrong&&!ok,
    seconds:quizFirstAttemptWrong?(quizFirstAttemptSeconds||attemptSeconds):attemptSeconds,
    nextDue:st.due,
    stability:st.stability,
    technique:String(quizMode).startsWith('rx:')?String(quizMode).split(':')[1]:null,
    techniqueData:safeTechniqueSnapshot()
  });

  // 誤答時は、答えを確認した直後に次の学習段階を見えるようにする。
  // v120: review journey is registered silently; surface it later, not inside the current question.

  saveProfile();
  document.getElementById('quizSubmit').textContent=
    quizIndex===quizItems.length-1 ? '結果を見る' : '次の問題 →';
  document.getElementById('quizProgress').style.width=`${((quizIndex+1)/quizItems.length)*100}%`;
}

function finishMock(timeup=false){
  recordMockQuestionTime();
  if(mockTimerHandle){clearInterval(mockTimerHandle);mockTimerHandle=null;}
  const used=Math.min(mockInitialSeconds,Math.max(0,mockInitialSeconds-mockSeconds));
  let correct=0,blank=0;
  const byCat={};
  const wrongs=[];

  mockItems.forEach((q,i)=>{
    const ans=mockAnswers[i];
    const ok=ans===q.a;
    const sourceId=q.sourceId||q.id;
    const ms=profile.mockQuestionStats[sourceId]||(profile.mockQuestionStats[sourceId]={seen:0,correct:0,lastSeen:null});
    ms.seen=(ms.seen||0)+1;
    if(ok)ms.correct=(ms.correct||0)+1;
    ms.lastSeen=localDateISO(0);
    if(ans===null) blank++;
    if(ok) correct++;
    if(!byCat[q.cat]) byCat[q.cat]={correct:0,total:0};
    byCat[q.cat].total++;
    if(ok) byCat[q.cat].correct++;
    ensureQuestionProfile();
    const st=profile.qStats[q.sourceId||q.id];
    const sec=mockQuestionSeconds[i]||0;
    if(!ok){
      wrongs.push({q,ans});
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.last=localDateISO(0);
        st.streak=0;
        if(ans===null && timeup) st.lastReason='時間不足';
        adaptiveMemoryUpdate(st,'wrong',sec,st.lastReason,false);
      }
      registerReviewJourney(q,'mock');
      applyQuestionSkillDelta(q,-1);
    }else{
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.correct=(st.correct||0)+1;
        st.last=localDateISO(0);
        st.streak=(st.streak||0)+1;
        adaptiveMemoryUpdate(st,'correct',sec,null,false);
      }
      applyQuestionSkillDelta(q,0.35);
    }
  });

  const total=mockItems.length;
  const rate=total?Math.round(correct/total*100):0;
  const wrong=total-correct-blank;

  const attemptDetails=mockItems.map((q,i)=>({
    id:q.sourceId||q.id,
    shownOptions:[...q.options],
    correctIndex:q.a,
    answerIndex:mockAnswers[i],
    flagged:!!mockFlags[i],
    seconds:mockQuestionSeconds[i]||0
  }));
  lastMockAttempt={
    date:localDateISO(0),mode:mockMode,total,correct,blank,rate,seconds:used,
    blueprint:mockCurrentBlueprint?structuredClone(mockCurrentBlueprint):null,
    byCat:structuredClone(byCat),details:attemptDetails
  };
  profile.mockHistory.unshift(lastMockAttempt);
  profile.mockHistory=profile.mockHistory.slice(0,10);
  profile.xp += Math.round(correct*2);
  saveProfile();

  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.add('show');

  document.getElementById('mockResultScore').textContent=`${rate}%`;
  document.getElementById('mockStatCorrect').textContent=correct;
  document.getElementById('mockStatWrong').textContent=wrong;
  document.getElementById('mockStatBlank').textContent=blank;
  document.getElementById('mockStatTime').textContent=`${Math.floor(used/60)}m`;

  let message='弱点を見つけられたことが収穫です。';
  let icon='📚';
  if(rate>=85){message='かなり安定しています。見直し問題を中心に仕上げましょう。';icon='🏆';}
  else if(rate>=70){message='良い位置です。誤答分野を復習するとさらに安定します。';icon='🎯';}
  else if(rate>=55){message='基礎はつながっています。弱点の再学習を優先しましょう。';icon='📈';}
  if(timeup) message='時間終了です。未回答を含めて、時間配分も復習材料にしましょう。';
  document.getElementById('mockResultIcon').textContent=icon;
  document.getElementById('mockResultMessage').textContent=message;
  renderMockDiagnosis(lastMockAttempt,byCat);

  const breakdown=document.getElementById('mockBreakdown');
  breakdown.innerHTML='';
  Object.entries(byCat).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total)).forEach(([cat,v])=>{
    const pct=Math.round(v.correct/v.total*100);
    const d=document.createElement('div');
    d.className='mock-break-row';
    d.innerHTML=`<div class="mock-break-name">${cat}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="mock-break-pct">${pct}%</div>`;
    breakdown.appendChild(d);
  });

  const review=document.getElementById('mockReviewList');
  review.innerHTML='';
  wrongs.slice(0,8).forEach(x=>{
    const d=document.createElement('div');
    d.className='mock-review-item';
    const selected=x.ans===null?'未回答':x.q.options[x.ans];
    const stat=profile.mockMistakeStats?.[x.q.sourceId||x.q.id];
    const j=journeyFor(x.q.sourceId||x.q.id);
    const reason=stat?.lastReason||'原因未記録';
    d.innerHTML=`<b>${x.q.cat}・${x.q.concept}</b><div class="sub">${escapeHtml(x.q.q)}<br>あなた：${escapeHtml(selected)} ／ 正解：${escapeHtml(x.q.options[x.q.a])}</div><div class="sub">原因：${escapeHtml(reason)}${j?` ／ 復習：${journeyStageLabel(j.stage)}`:''}</div>`;
    review.appendChild(d);
  });
  if(!wrongs.length) review.innerHTML='<div class="sub">全問正解です 🎉</div>';

  const reviewBtn=document.getElementById('mockStartReview');
  if(reviewBtn){
    const hasReview=reviewCandidates(lastMockAttempt).length>0;
    reviewBtn.style.display=hasReview?'':'none';
    reviewBtn.classList.toggle('primary-action',hasReview);
    document.getElementById('mockBackMenu')?.classList.toggle('primary-action',!hasReview);
  }
  renderMockHistory();
  renderDailyPlan();
  renderReadiness();
}

function ensureQuestionProfile(){
  if(!profile.qStats) profile.qStats={};
  if(!profile.sessions) profile.sessions=[];
  const trackedQuestions=trackedQuestionPool();
  trackedQuestions.forEach(q=>{
    if(!profile.qStats[q.id]){
      profile.qStats[q.id]={
        attempts:0, correct:0, streak:0,
        due:null, last:null, lastReason:null
      };
    }
    const st=profile.qStats[q.id];
    if(st.stability==null){
      const s=st.streak||0;
      st.stability=s<=0?1:s===1?3:s===2?7:s===3?14:30;
    }
    if(st.lapses==null) st.lapses=0;
    if(st.reviews==null) st.reviews=0;
    if(st.avgSeconds==null) st.avgSeconds=0;
    if(st.timedAnswers==null) st.timedAnswers=0;
    if(st.lastQuality==null) st.lastQuality=null;
    if(st.lastReviewDate==null) st.lastReviewDate=st.last||null;
    if(st.recovered==null) st.recovered=0;
    if(st.retryFailures==null) st.retryFailures=0;
    if((st.memoryVersion||0)<2) st.memoryVersion=2;
  });
}

function markJourneyAnswer(id,firstTryCorrect){
  const j=journeyFor(id);if(!j)return;
  if(firstTryCorrect){
    if(j.stage==='verify'){j.stage='spaced';j.verifyDone=localDateISO(0);j.due=profile.qStats?.[id]?.due||localDateISO(2);}
    else if(j.stage==='spaced'){j.stage='stable';j.spacedDone=localDateISO(0);j.completedAt=localDateISO(0);}
  }else{j.stage='verify';j.due=localDateISO(1);}
  saveProfile();
}

function registerReviewJourney(q,source='practice'){
  const id=q?.sourceId||q?.id;if(!id)return null;
  const base=questionById(id)||q;
  const old=profile.reviewJourneys[id]||{};
  const lessonId=lessonForQuestion(base);
  const wasStable=old.stage==='stable';
  profile.reviewJourneys[id]={
    ...old,id,cat:base.cat,concept:base.concept,lessonId,
    stage:wasStable?(lessonId?'relearn':'verify'):(old.stage|| (lessonId?'relearn':'verify')),
    misses:(old.misses||0)+1,lastWrong:localDateISO(0),source,
    due:profile.qStats?.[id]?.due||localDateISO(1),completedAt:wasStable?null:old.completedAt
  };
  saveProfile();
  return profile.reviewJourneys[id];
}

function chooseTaperReviewQuestions(n=5){
  ensureQuestionProfile();
  const due=dueQuestions();
  const used=new Set();
  const out=[];
  const add=q=>{if(q&&!used.has(q.id)&&out.length<n){out.push(q);used.add(q.id);}};
  due.slice(0,n).forEach(add);
  if(out.length<n){
    trackedQuestionPool()
      .filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!used.has(q.id)&&!questionHasActiveJourney(q.id))
      .sort((a,b)=>reviewUrgency(b)-reviewUrgency(a))
      .slice(0,n-out.length).forEach(add);
  }
  if(out.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-out.length).forEach(add);
  }
  return out.map(buildReviewItem);
}

function coreTopicLearningState(id){
  const lessonPct=profile.lessonProgress?.[id]||0;
  const topic=CORE_A_TOPIC_MAP[id]||CORE_A_CURRICULUM.find(t=>t.id===id);
  const qs=QUESTION_BANK.filter(q=>q.coreTopicId===id&&isCoreTopicImmediatePracticeQuestion(q));
  const stats=qs.map(q=>({q,st:profile.qStats?.[q.id]||{}}));
  const attempted=stats.filter(x=>(x.st.attempts||0)>0).length;
  const active=stats.filter(x=>questionHasActiveJourney(x.q.id)).length;
  const due=stats.filter(x=>isDue(x.st)&&!questionHasActiveJourney(x.q.id)).length;
  const reviewed=stats.filter(x=>(x.st.reviews||0)>=2).length;

  const retentionRows=stats
    .filter(x=>(x.st.attempts||0)>0)
    .map(x=>({ret:memoryRetention(x.st),weight:cognitiveWeight(x.q)}))
    .filter(x=>x.ret!=null);
  const retention=retentionRows.length
    ?Math.round(retentionRows.reduce((a,x)=>a+x.ret*x.weight,0)/Math.max(1,retentionRows.reduce((a,x)=>a+x.weight,0)))
    :null;
  const minRetention=retentionRows.length?Math.min(...retentionRows.map(x=>x.ret)):null;

  // 「定着」には最低1問の高次証拠、「MASTER」にはさらに高い保持を要求する。
  const judgmentStats=stats.filter(x=>x.q.cognitiveLevel==='判断');
  const evidencePool=judgmentStats.length?judgmentStats:stats.filter(x=>x.q.cognitiveLevel==='適用');
  const advancedReviewed=evidencePool.filter(x=>(x.st.reviews||0)>=2).length;
  const advancedRows=evidencePool
    .filter(x=>(x.st.attempts||0)>0)
    .map(x=>memoryRetention(x.st))
    .filter(x=>x!=null);
  const advancedRetention=advancedRows.length?Math.round(advancedRows.reduce((a,b)=>a+b,0)/advancedRows.length):null;
  const advancedReady=evidencePool.length===0||(advancedReviewed>=1&&advancedRetention!=null&&advancedRetention>=80);
  const advancedMasterReady=evidencePool.length===0||(advancedReviewed>=1&&advancedRetention!=null&&advancedRetention>=90);

  // 習得状態は単一テーマ内だけで完結させず、その章の統合演習も通過して初めて付与する。
  const chapterEvidence=chapterIntegrationEvidence(topic?.chapter||0);
  const chapterReady=!!chapterEvidence.passed;

  const common={attempted,total:qs.length,active,due,reviewed,retention,minRetention,advancedReady,advancedMasterReady,advancedReviewed,advancedRetention,chapterReady,chapterRate:chapterEvidence.lastRate||0,chapterBestRate:chapterEvidence.bestRate||0};

  if(lessonPct<100){
    return {key:attempted?'learning':'new',label:attempted?'学習中':'未習得',...common};
  }
  if(!attempted){
    return {key:'learning',label:'学習中',...common};
  }
  if(active){
    return {key:'review',label:`要復習 ${active}`,...common};
  }
  if(attempted<qs.length){
    return {key:'learning',label:'学習中',...common};
  }

  const topicMasterReady=
    reviewed===qs.length &&
    retention!=null && retention>=90 &&
    minRetention!=null && minRetention>=85 &&
    due===0 &&
    advancedMasterReady;

  if(topicMasterReady&&chapterReady){
    return {key:'master',label:'習得',...common};
  }
  if(reviewed>=Math.ceil(qs.length*.6)&&retention!=null&&retention>=80&&due===0&&advancedReady){
    return {key:'stable',label:topicMasterReady&&!chapterReady?'定着・章末待ち':'定着',...common};
  }
  if(!advancedReady&&attempted===qs.length&&due===0){
    return {key:'understood',label:'理解・実戦待ち',...common};
  }
  return {key:'understood',label:due?`理解・復習${due}`:'理解',...common};
}

function estimateRemainingStudyMinutes(){
  let m=0;
  (typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS||{})).forEach(id=>{const p=clamp(profile.lessonProgress?.[id]||0,0,100);m+=(1-p/100)*14;});
  (QUESTION_BANK||[]).forEach(q=>{if(!((profile.qStats?.[q.id]?.attempts||0)>0))m+=2.5;});
  (B_EXERCISES||[]).forEach(x=>{const p=clamp(profile.bProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  (SECURITY_SCENARIOS||[]).forEach(x=>{const p=clamp(profile.securityBProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  const a=(profile.mockHistory||[]).filter(x=>x.mode==='full').length,b=(profile.bFinalHistory||[]).length;
  m+=Math.max(0,2-a)*90+Math.max(0,2-b)*100+Math.max(0,1-(profile.bMockHistory||[]).length)*40+Math.max(0,1-(profile.securityMockHistory||[]).length)*20+Math.max(0,3-(profile.bCompoundHistory||[]).length)*20;
  const active=activeReviewJourneys().length;
  m+=Math.min(240,active*8+dueQuestions().length*3);
  return Math.max(0,Math.round(m));
}

function repeatedWrongQuestions(){
  return trackedQuestionPool().map(q=>{
    const st=profile.qStats?.[q.id]||{};
    const ordinary=Math.max(0,(st.attempts||0)-(st.correct||0));
    const mock=profile.mockMistakeStats?.[q.id]?.misses||0;
    return {q,count:Math.max(ordinary,mock),reason:reasonForQuestion(q.id),due:st.due||''};
  }).filter(x=>x.count>=2).sort((a,b)=>b.count-a.count).slice(0,6);
}

function reviewForecast(days=7){
  ensureQuestionProfile();
  const out=[];
  for(let i=0;i<days;i++){
    const date=localDateISO(i);
    let count=0;
    trackedQuestionPool().forEach(q=>{
      const st=profile.qStats[q.id];
      if(!(st?.attempts>0) || !st.due) return;
      if(i===0){
        if(st.due<=date) count++;
      }else if(st.due===date) count++;
    });
    out.push({date,offset:i,count});
  }
  return out;
}

