  root.innerHTML=output||'<div class="empty">該当するテーマがありません。</div>';
}

function courseAContinueId(){
  const ui=readUiState();
  if(ui.lessonId&&CORE_A_IDS.includes(ui.lessonId)&&(profile.lessonProgress?.[ui.lessonId]||0)<100)return ui.lessonId;
  return nextLessonChoice()?.id||null;
}

function examAreaProgress(area){
  if(area.special==='b'){
    const a=objectCompletion(profile.bProgress,B_EXERCISES.length);
    const s=objectCompletion(profile.securityBProgress,SECURITY_SCENARIOS.length);
    return Math.round((a+s)/2);
  }
  const valid=(area.ids||[]).filter(id=>LESSONS[id]);
  if(!valid.length) return 0;
  return Math.round(valid.reduce((sum,id)=>sum+(profile.lessonProgress?.[id]||0),0)/valid.length);
}

function lessonCompletionAverage(ids=null){
  const all=ids || (typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS||{}));
  if(!all.length) return 0;
  return Math.round(all.reduce((s,id)=>s+(profile.lessonProgress?.[id]||0),0)/all.length);
}

function nextLessonChoice(){
  const weakOrder=sortedSkills().map(x=>x[0]);
  for(const skill of weakOrder){
    const ids=CORE_A_IDS.filter(id=>LESSONS[id].skill===skill);
    const incomplete=ids.find(id=>(profile.lessonProgress?.[id]||0)<100);
    if(incomplete) return {id:incomplete,skill,title:LESSONS[incomplete].title};
  }
  return {id:null,skill:weakOrder[0]||'基礎理論',title:'科目A教材 130テーマ完了',complete:true};
}

