function subjectBMarkAlgorithmDomainTraceCompleteV227(traceId){
  const context=subjectBAlgorithmDomainContextV227();
  const marker=profile.subjectBAlgorithmDomainV227;
  if(marker&&marker.firstFinalKey===subjectBFirstFinalKeyV222(profile.bFinalHistory?.[0])&&!marker.completed&&marker.targetId===traceId){
    marker.completed=true;
    marker.completedAt=localDateISO(0);
    return true;
  }
  if(context&&context.target.id===traceId){
    profile.subjectBAlgorithmDomainV227=subjectBAlgorithmDomainMarkerV227(context,true);
    profile.subjectBAlgorithmDomainV227.completedAt=localDateISO(0);
    return true;
  }
  return false;
}

function nextBChoice(minutes=20){
  const algoTotal=B_EXERCISES.length;
  const secTotal=SECURITY_SCENARIOS.length;
  const algoDone=B_EXERCISES.filter(x=>(profile.bProgress?.[x.id]||0)>=100).length;
  const secDone=SECURITY_SCENARIOS.filter(x=>(profile.securityBProgress?.[x.id]||0)>=100).length;
  const algoRate=algoDone/Math.max(1,algoTotal);
  const secRate=secDone/Math.max(1,secTotal);

  if(algoDone<algoTotal || secDone<secTotal){
    if(algoRate<=secRate && algoDone<algoTotal){
      const ex=B_EXERCISES.find(x=>(profile.bProgress?.[x.id]||0)<100) || B_EXERCISES[0];
      return {mode:'trace',id:ex?.id,title:ex?.title||'アルゴリズムトレース'};
    }
    const sc=SECURITY_SCENARIOS.find(x=>(profile.securityBProgress?.[x.id]||0)<100) || SECURITY_SCENARIOS[0];
    return {mode:'security',id:sc?.id,title:sc?.title||'セキュリティ演習'};
  }

  // 通常の20分枠に100分の総合実戦を自動割当しない。
  // 基礎演習完了後は20分の複合演習とセキュリティ実戦を交互に回す。
  const compoundRuns=(profile.bCompoundHistory||[]).length;
  const securityRuns=(profile.securityMockHistory||[]).length;
  if(compoundRuns<=securityRuns)return {mode:'compound',id:null,title:'複合問題・3問'};
  return {mode:'securityMock',id:null,title:'セキュリティ ミニ模試'};
}

function normalizeProfileData(input){
  const migration=migrateProfileData(input);
  const p=migration.profile;
  const out={...structuredClone(DEFAULT_PROFILE),...p};
  out.profileSchemaVersion=PROFILE_SCHEMA_VERSION;
  out.profileMeta={...structuredClone(DEFAULT_PROFILE.profileMeta),...safeObject(p.profileMeta)};
  out.profileMeta.revision=nonNegativeInt(out.profileMeta.revision,0);
  out.profileMeta.lastWriterId=typeof out.profileMeta.lastWriterId==='string'?out.profileMeta.lastWriterId:null;
  out.masteryHistory=safeObject(p.masteryHistory);
  out.xp=nonNegativeInt(p.xp,0);
  out.streak=nonNegativeInt(p.streak,0);
  out.diagnosticCompleted=!!p.diagnosticCompleted;
  out.diagnosticScores=safeObject(p.diagnosticScores);
  out.skills={};
