  const statId=q.sourceId||q.id;
  const st=profile.qStats[statId];
  const selectedNow=quizSelected;
  const attemptSeconds=Math.max(1,Math.round((Date.now()-quizQuestionStartedAt)/1000));

  // 通常演習ではすべて「初回誤答→ヒント→1回だけ再挑戦」に統一する。
  // v121: 誤答時はヒント本文だけを表示し、採点ルールやメタ説明は出さない。
  // 模試は別の試験UIなので、この関数を通らない。
  if(!ok && quizRetryCount===0){
    quizRetryCount=1;
    quizFirstAttemptWrong=true;
    quizWrongCount++;
    quizFirstAttemptSeconds=attemptSeconds;

    // 成績・正答率・忘却モデルへ入れるのは最初の回答だけ。
    st.attempts++;
    st.last=localDateISO(0);
    st.streak=0;
    adaptiveMemoryUpdate(st,'wrong',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,-1);
    profile.xp+=2;
    registerReviewJourney(q,String(quizMode).startsWith('journey:')?'journey':'practice');
    saveProfile();

    const selectedBtn=document.querySelectorAll('.quiz-option')[selectedNow];
    if(selectedBtn){
      selectedBtn.classList.remove('selected');
      selectedBtn.classList.add('first-wrong');
      selectedBtn.disabled=true;
    }
    quizSelected=null;
    quizQuestionStartedAt=Date.now();

    document.getElementById('quizResultTitle').textContent='💡 ヒント';
    document.getElementById('quizExplanation').textContent=q.hint;
    document.getElementById('quizHint').textContent='';
    document.getElementById('quizExplain').classList.add('show');
    document.getElementById('quizHintBtn').style.display='none';
    document.querySelector('.quiz-actions')?.classList.add('single-primary');
    document.getElementById('quizSubmit').textContent='もう一度回答する';
    return;
  }

  quizAnswered=true;
  stopQuestionPacer();

  document.querySelectorAll('.quiz-option').forEach((btn,i)=>{
    btn.disabled=true;
    btn.classList.remove('selected','first-wrong');
    if(i===q.a) btn.classList.add('correct');
    else if(i===selectedNow && !ok) btn.classList.add('wrong');
  });

  const recovered=ok && quizFirstAttemptWrong;
  document.getElementById('quizResultTitle').textContent=recovered?'🔄 再挑戦で正解！':ok?'⭕ 正解！':'❌ 不正解';
  renderFinalQuizExplanation(q);
  const finalHint=(q.hint && !String(q.exp||'').includes(q.hint))?`確認ポイント：${q.hint}`:'';
  document.getElementById('quizHint').textContent=finalHint;
  document.getElementById('quizExplain').classList.add('show');
  document.getElementById('quizHintBtn').style.display='none';
  document.querySelector('.quiz-actions')?.classList.add('single-primary');

  const answerExplain=document.getElementById('quizExplain');
  answerExplain.querySelector('.variant-source-note')?.remove();
  answerExplain.querySelector('.review-route-inline')?.remove();
  answerExplain.querySelector('.memory-next-note')?.remove();
  const retryNote=answerExplain.querySelector('.retry-note');
  if(retryNote) retryNote.remove();

  if(!quizFirstAttemptWrong){
    // 初回正解だけが「正解」として正答率へ入る。
    quizCorrectCount++;
    quizEarnedXp+=10;
    st.attempts++;
    st.correct++;
    st.last=localDateISO(0);
    st.streak=(st.streak||0)+1;
    adaptiveMemoryUpdate(st,'correct',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,1);
    profile.xp+=10;
  }else if(recovered){
    // 再挑戦成功は別指標。attempts/correctは増やさない。
    quizRecoveredCount++;
    st.recovered=(st.recovered||0)+1;
    st.streak=0;
    adaptiveMemoryUpdate(st,'recovered',quizFirstAttemptSeconds||attemptSeconds,quizPickedReason,true);
    applyQuestionSkillDelta(q,0.25);
    profile.xp+=5;
  }else{
    // 2回目も不正解でも、同じ問題を2回誤答として数えない。
    st.retryFailures=(st.retryFailures||0)+1;
  }

  // 最初に間違えた問題は、再挑戦で正解しても原因を記録できる。
  if(quizFirstAttemptWrong) document.getElementById('reasonBox').classList.add('show');

  if(String(quizMode).startsWith('journey:')){
    const jid=String(quizMode).slice(8);
    markJourneyAnswer(jid,!quizFirstAttemptWrong&&ok);
  }

  sessionLog.push({
    id:statId,variantId:q.variant?q.id:null,cat:q.cat,concept:q.concept,
    ok:!quizFirstAttemptWrong&&ok,
    recovered,
    retryFailed:quizFirstAttemptWrong&&!ok,
    seconds:quizFirstAttemptWrong?(quizFirstAttemptSeconds||attemptSeconds):attemptSeconds,
    nextDue:st.due,
    stability:st.stability,
    technique:String(quizMode).startsWith('rx:')?String(quizMode).split(':')[1]:null,
    techniqueData:safeTechniqueSnapshot()
  });

  // 誤答時は、答えを確認した直後に次の学習段階を見えるようにする。
  // v120: review journey is registered silently; surface it later, not inside the current question.

  saveProfile();
  document.getElementById('quizSubmit').textContent=
    quizIndex===quizItems.length-1 ? '結果を見る' : '次の問題 →';
  document.getElementById('quizProgress').style.width=`${((quizIndex+1)/quizItems.length)*100}%`;
}

function finishMock(timeup=false){
  recordMockQuestionTime();
  if(mockTimerHandle){clearInterval(mockTimerHandle);mockTimerHandle=null;}
  const used=Math.min(mockInitialSeconds,Math.max(0,mockInitialSeconds-mockSeconds));
  let correct=0,blank=0;
  const byCat={};
  const wrongs=[];

  mockItems.forEach((q,i)=>{
    const ans=mockAnswers[i];
    const ok=ans===q.a;
    const sourceId=q.sourceId||q.id;
    const ms=profile.mockQuestionStats[sourceId]||(profile.mockQuestionStats[sourceId]={seen:0,correct:0,lastSeen:null});
    ms.seen=(ms.seen||0)+1;
    if(ok)ms.correct=(ms.correct||0)+1;
    ms.lastSeen=localDateISO(0);
    if(ans===null) blank++;
    if(ok) correct++;
    if(!byCat[q.cat]) byCat[q.cat]={correct:0,total:0};
    byCat[q.cat].total++;
    if(ok) byCat[q.cat].correct++;
    ensureQuestionProfile();
    const st=profile.qStats[q.sourceId||q.id];
    const sec=mockQuestionSeconds[i]||0;
    if(!ok){
      wrongs.push({q,ans});
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.last=localDateISO(0);
        st.streak=0;
        if(ans===null && timeup) st.lastReason='時間不足';
        adaptiveMemoryUpdate(st,'wrong',sec,st.lastReason,false);
      }
      registerReviewJourney(q,'mock');
      applyQuestionSkillDelta(q,-1);
    }else{
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.correct=(st.correct||0)+1;
        st.last=localDateISO(0);
        st.streak=(st.streak||0)+1;
        adaptiveMemoryUpdate(st,'correct',sec,null,false);
      }
      applyQuestionSkillDelta(q,0.35);
    }
  });

  const total=mockItems.length;
  const rate=total?Math.round(correct/total*100):0;
  const wrong=total-correct-blank;

  const attemptDetails=mockItems.map((q,i)=>({
    id:q.sourceId||q.id,
    shownOptions:[...q.options],
    correctIndex:q.a,
    answerIndex:mockAnswers[i],
    flagged:!!mockFlags[i],
    seconds:mockQuestionSeconds[i]||0
  }));
  lastMockAttempt={
    date:localDateISO(0),mode:mockMode,total,correct,blank,rate,seconds:used,
    blueprint:mockCurrentBlueprint?structuredClone(mockCurrentBlueprint):null,
    byCat:structuredClone(byCat),details:attemptDetails
  };
  profile.mockHistory.unshift(lastMockAttempt);
  profile.mockHistory=profile.mockHistory.slice(0,10);
  profile.xp += Math.round(correct*2);
  saveProfile();

  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.add('show');

  document.getElementById('mockResultScore').textContent=`${rate}%`;
  document.getElementById('mockStatCorrect').textContent=correct;
  document.getElementById('mockStatWrong').textContent=wrong;
  document.getElementById('mockStatBlank').textContent=blank;
  document.getElementById('mockStatTime').textContent=`${Math.floor(used/60)}m`;

  let message='弱点を見つけられたことが収穫です。';
  let icon='📚';
  if(rate>=85){message='かなり安定しています。見直し問題を中心に仕上げましょう。';icon='🏆';}
  else if(rate>=70){message='良い位置です。誤答分野を復習するとさらに安定します。';icon='🎯';}
  else if(rate>=55){message='基礎はつながっています。弱点の再学習を優先しましょう。';icon='📈';}
  if(timeup) message='時間終了です。未回答を含めて、時間配分も復習材料にしましょう。';
  document.getElementById('mockResultIcon').textContent=icon;
  document.getElementById('mockResultMessage').textContent=message;
  renderMockDiagnosis(lastMockAttempt,byCat);

  const breakdown=document.getElementById('mockBreakdown');
  breakdown.innerHTML='';
  Object.entries(byCat).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total)).forEach(([cat,v])=>{
    const pct=Math.round(v.correct/v.total*100);
    const d=document.createElement('div');
    d.className='mock-break-row';
    d.innerHTML=`<div class="mock-break-name">${cat}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="mock-break-pct">${pct}%</div>`;
    breakdown.appendChild(d);
  });

  const review=document.getElementById('mockReviewList');
  review.innerHTML='';
  wrongs.slice(0,8).forEach(x=>{
    const d=document.createElement('div');
    d.className='mock-review-item';
    const selected=x.ans===null?'未回答':x.q.options[x.ans];
    const stat=profile.mockMistakeStats?.[x.q.sourceId||x.q.id];
    const j=journeyFor(x.q.sourceId||x.q.id);
    const reason=stat?.lastReason||'原因未記録';
    d.innerHTML=`<b>${x.q.cat}・${x.q.concept}</b><div class="sub">${escapeHtml(x.q.q)}<br>あなた：${escapeHtml(selected)} ／ 正解：${escapeHtml(x.q.options[x.q.a])}</div><div class="sub">原因：${escapeHtml(reason)}${j?` ／ 復習：${journeyStageLabel(j.stage)}`:''}</div>`;
    review.appendChild(d);
  });
  if(!wrongs.length) review.innerHTML='<div class="sub">全問正解です 🎉</div>';

  const reviewBtn=document.getElementById('mockStartReview');
  if(reviewBtn){
    const hasReview=reviewCandidates(lastMockAttempt).length>0;
    reviewBtn.style.display=hasReview?'':'none';
    reviewBtn.classList.toggle('primary-action',hasReview);
    document.getElementById('mockBackMenu')?.classList.toggle('primary-action',!hasReview);
  }
  renderMockHistory();
  renderDailyPlan();
  renderReadiness();
}

function markJourneyAnswer(id,firstTryCorrect){
  const j=journeyFor(id);if(!j)return;
  if(firstTryCorrect){
    if(j.stage==='verify'){j.stage='spaced';j.verifyDone=localDateISO(0);j.due=profile.qStats?.[id]?.due||localDateISO(2);}
    else if(j.stage==='spaced'){j.stage='stable';j.spacedDone=localDateISO(0);j.completedAt=localDateISO(0);}
  }else{j.stage='verify';j.due=localDateISO(1);}
  saveProfile();
}

function registerReviewJourney(q,source='practice'){
  const id=q?.sourceId||q?.id;if(!id)return null;
  const base=questionById(id)||q;
  const old=profile.reviewJourneys[id]||{};
  const lessonId=lessonForQuestion(base);
  const wasStable=old.stage==='stable';
  profile.reviewJourneys[id]={
    ...old,id,cat:base.cat,concept:base.concept,lessonId,
    stage:wasStable?(lessonId?'relearn':'verify'):(old.stage|| (lessonId?'relearn':'verify')),
    misses:(old.misses||0)+1,lastWrong:localDateISO(0),source,
    due:profile.qStats?.[id]?.due||localDateISO(1),completedAt:wasStable?null:old.completedAt
  };
  saveProfile();
  return profile.reviewJourneys[id];
}

function chooseTaperReviewQuestions(n=5){
  ensureQuestionProfile();
  const due=dueQuestions();
  const used=new Set();
  const out=[];
  const add=q=>{if(q&&!used.has(q.id)&&out.length<n){out.push(q);used.add(q.id);}};
  due.slice(0,n).forEach(add);
  if(out.length<n){
    trackedQuestionPool()
      .filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!used.has(q.id)&&!questionHasActiveJourney(q.id))
      .sort((a,b)=>reviewUrgency(b)-reviewUrgency(a))
      .slice(0,n-out.length).forEach(add);
  }
  if(out.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-out.length).forEach(add);
  }
  return out.map(buildReviewItem);
}

function estimateRemainingStudyMinutes(){
  let m=0;
  (typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS||{})).forEach(id=>{const p=clamp(profile.lessonProgress?.[id]||0,0,100);m+=(1-p/100)*14;});
  (QUESTION_BANK||[]).forEach(q=>{if(!((profile.qStats?.[q.id]?.attempts||0)>0))m+=2.5;});
  (B_EXERCISES||[]).forEach(x=>{const p=clamp(profile.bProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  (SECURITY_SCENARIOS||[]).forEach(x=>{const p=clamp(profile.securityBProgress?.[x.id]||0,0,100);m+=(1-p/100)*15;});
  const a=(profile.mockHistory||[]).filter(x=>x.mode==='full').length,b=(profile.bFinalHistory||[]).length;
  m+=Math.max(0,2-a)*90+Math.max(0,2-b)*100+Math.max(0,1-(profile.bMockHistory||[]).length)*40+Math.max(0,1-(profile.securityMockHistory||[]).length)*20+Math.max(0,3-(profile.bCompoundHistory||[]).length)*20;
  const active=activeReviewJourneys().length;
  m+=Math.min(240,active*8+dueQuestions().length*3);
  return Math.max(0,Math.round(m));
}

