function finalFocusRecommendation(status=courseMasteryStatus()){
  const days=examDaysRemaining();
  const urgentPhase=days!=null&&days>=0&&days<=14;
  const deepTaper=days!=null&&days>=0&&days<=3;
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;

  if(days===0){
    return {kind:'warmup',icon:'☀️',title:'今日は3問だけ確認',desc:'新規教材も長時間模試も追加しません。既習3問で感覚だけ整えます。',button:'ウォームアップ3問'};
  }
