function ensureQuestionProfile(){
  if(!profile.qStats) profile.qStats={};
  if(!profile.sessions) profile.sessions=[];
  const trackedQuestions=trackedQuestionPool();
  trackedQuestions.forEach(q=>{
    if(!profile.qStats[q.id]){
      profile.qStats[q.id]={
        attempts:0, correct:0, streak:0,
        due:null, last:null, lastReason:null
      };
    }
    const st=profile.qStats[q.id];
    if(st.stability==null){
      const s=st.streak||0;
      st.stability=s<=0?1:s===1?3:s===2?7:s===3?14:30;
    }
    if(st.lapses==null) st.lapses=0;
    if(st.reviews==null) st.reviews=0;
    if(st.avgSeconds==null) st.avgSeconds=0;
    if(st.timedAnswers==null) st.timedAnswers=0;
    if(st.lastQuality==null) st.lastQuality=null;
    if(st.lastReviewDate==null) st.lastReviewDate=st.last||null;
    if(st.recovered==null) st.recovered=0;
    if(st.retryFailures==null) st.retryFailures=0;
    if((st.memoryVersion||0)<2) st.memoryVersion=2;
  });
}

function analyticsAttemptStream(){
  const rows=[];
  (profile.sessions||[]).forEach((s,si)=>(s.log||[]).forEach((x,li)=>rows.push({date:s.date,cat:x.cat,ok:!!x.ok,order:si*100+li,source:'session'})));
  (profile.mockHistory||[]).forEach((h,hi)=>(h.details||[]).forEach((d,di)=>{
    const q=QUESTION_BANK.find(x=>x.id===d.id);if(!q)return;
    rows.push({date:h.date,cat:q.cat,ok:d.answerIndex!==null&&d.answerIndex===d.correctIndex,order:hi*100+di+50000,source:'mock'});
  }));
  return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date))||a.order-b.order);
}

function renderExerciseEntry(){
  const card=document.getElementById('exerciseNextCard');
  const icon=document.getElementById('exerciseNextIcon');
  const kicker=document.getElementById('exerciseNextKicker');
  const title=document.getElementById('exerciseNextTitle');
  const desc=document.getElementById('exerciseNextDesc');
  const action=document.getElementById('exerciseNextAction');
  if(!card||!icon||!kicker||!title||!desc||!action)return;

  const journey=actionableReviewJourneys()[0];
  const due=dueQuestions().length;
  const nextDaily=nextUnfinishedDailyTask();
  action.disabled=false;
  kicker.textContent='次におすすめ';

  if(journey){
    icon.textContent='🔁';
    title.textContent=`${journey.concept}の復習を続ける`;
    desc.textContent=journeyGuidance(journey);
    action.textContent=journey.stage==='relearn'?'教材で確認 →':journey.stage==='verify'?'別問題で確認 →':'定着を確認 →';
    action.onclick=()=>startJourneyAction(journey.id);
    return;
  }
  if(due>0){
    icon.textContent='🧠';
    title.textContent=`今日の復習 ${Math.min(due,10)}問`;
    desc.textContent=`復習タイミングの問題が${due}問あります。忘却リスクが高い順に確認します。`;
    action.textContent='復習を始める →';
    action.onclick=()=>startQuiz('review');
    return;
  }
  if(nextDaily && ['boss','warmup','taperReview'].includes(nextDaily.type)){
    icon.textContent=nextDaily.icon||'✅';
    kicker.textContent='今日の計画';
    title.textContent=nextDaily.title;
    desc.textContent=`${nextDaily.minutes}分の予定です。今日の学習計画に沿って進めます。`;
    action.textContent='始める →';
    action.onclick=()=>launchDailyTask(nextDaily);
    return;
  }
  const rx=recommendedPrescription();
  const meta=prescriptionMeta(rx);
  icon.textContent=meta.icon||'🎯';
  title.textContent=profile.sessions?.length?meta.title:'弱点を10問で確認';
  desc.textContent=profile.sessions?.length?meta.desc:'復習待ちはありません。現在の習熟度が低い分野から10問を選びます。';
  action.textContent='始める →';
  action.onclick=()=>profile.sessions?.length?startRecommendedPrescription():startQuiz('weak');
}

function renderRecentHistory(){
  const root=document.getElementById('recentHistory');
  if(!root) return;
  ensureQuestionProfile();

  const sessions=(profile.sessions||[]).slice(0,4);
  if(!sessions.length){
    root.innerHTML='<div class="sub">まだ演習履歴がありません。</div>';
    return;
  }
  root.innerHTML='';
  const names={review:'今日の復習',weak:'弱点10問',random:'ランダム10問',boss:'今日の総合チェック'};
  sessions.forEach(s=>{
    const row=document.createElement('div');
    row.className='history-row';
    const good=s.rate>=70;
    row.innerHTML=`
      <div class="history-mark ${good?'ok':'ng'}">${good?'✓':'!'}</div>
      <div class="history-text">
        <div class="history-title">${String(s.mode).startsWith('rx:')?prescriptionMeta(s.mode).title:(names[s.mode]||'問題演習')}・${s.rate}%</div>
        <div class="history-sub">${s.date}　${s.correct}/${s.total}問正解</div>
      </div>
    `;
    root.appendChild(row);
  });
}

function(){
  const lessonBefore=activeLesson;
  const reviewBefore=activeReviewJourneyId?journeyFor(activeReviewJourneyId):null;
  const isReviewLesson=!!reviewBefore&&reviewBefore.stage==='relearn'&&reviewBefore.lessonId===lessonBefore;
  const isCoreLesson=!!LESSONS[lessonBefore]?.core;
  _completeLessonV65();

  // 科目Aコアは「教材を読む→テーマ演習を終える」までを今日の学習1枠とする。
  // 復習ルート内の教材読み直しは新規学習枠として数えない。
  if(!isReviewLesson&&!isCoreLesson)markDailyTask('lesson',{lessonId:lessonBefore});
}

function ensureChapterMasteryProfile(){
  if(!profile.chapterMastery) profile.chapterMastery={};

  // v95以前の直近セッションが残っている場合は、章末統合演習の結果を移行する。
  for(let ch=1;ch<=21;ch++){
    const key=String(ch);
    if(profile.chapterMastery[key])continue;
    const rows=(profile.sessions||[]).filter(x=>x.mode===`corechapter:${ch}`);
    if(!rows.length)continue;
    const latest=rows[0];
    profile.chapterMastery[key]={
      attempts:rows.length,
      passes:rows.filter(x=>(Number(x.rate)||0)>=80).length,
      bestRate:Math.max(...rows.map(x=>Number(x.rate)||0)),
      lastRate:Number(latest.rate)||0,
      lastDate:latest.date||null
    };
  }
}

function markDailyTask(type,meta={}){
  const rec=getDailyRecord(),tasks=ensureTodayPlanSnapshot();
  const task=tasks.find(t=>dailyTaskMatches(t,type,meta));
  if(!task)return false;
  const slot=dailyTaskSlot(task);
  if(!rec.done[slot]){
    rec.done[slot]=true;
    addActivity(task.minutes,slot);
  }else{
    persistProfileSilently();
  }
  renderDailyPlan();
  renderPlannerScreen();
  return true;
}

function recentQuizRate(){
  const s=(profile.sessions||[]).slice(0,5);
  if(!s.length) return 0;
  return Math.round(s.reduce((a,x)=>a+(x.rate||0),0)/s.length);
}

function(){
  const data=_roadmapDataV13();
  if(data.length){
    const mockCount=(profile.mockHistory||[]).length;
    const sessionCount=(profile.sessions||[]).length;
    const p=Math.min(100,Math.round(((mockCount*2+sessionCount)/12)*100));
    data[data.length-1].pct=Math.max(data[data.length-1].pct,p);
    data[data.length-1].desc='弱点演習・復習・科目A MOCK';
  }
  return data;
}
